import{_ as o,o as a,c as s,a0 as d}from"./chunks/framework.BGyYNsHo.js";const S=JSON.parse('{"title":"Formatos de datos","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/05-formatos-de-datos.md","filePath":"es/reference/05-formatos-de-datos.md"}'),t={name:"es/reference/05-formatos-de-datos.md"};function n(r,e,c,i,p,l){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="formatos-de-datos" tabindex="-1">Formatos de datos <a class="header-anchor" href="#formatos-de-datos" aria-label="Permalink to &quot;Formatos de datos&quot;">​</a></h1><p>Los tres formatos de datos que la app lee y escribe: el archivo de proyecto, el dialecto INP y el binario <code>.out</code>.</p><h2 id="archivo-de-proyecto-oswmm-json" tabindex="-1">Archivo de proyecto (<code>.oswmm.json</code>) <a class="header-anchor" href="#archivo-de-proyecto-oswmm-json" aria-label="Permalink to &quot;Archivo de proyecto (\`.oswmm.json\`)&quot;">​</a></h2><p>El JSON producido por <code>Net.serialize()</code> (<code>network.js:465-488</code>) — un snapshot completo de <code>{title, units, options, nodes, links, subcatchments, timeseries, curves, lidControls, lidUsages, pollutants, landUses, treatments, aquifers, snowpacks, snowpackAssignments, rawSections, …}</code>. Es lo que <strong>Save</strong> escribe y <strong>Load</strong> lee.</p><h2 id="dialecto-inp-swmm-estandar" tabindex="-1">Dialecto INP (SWMM estándar) <a class="header-anchor" href="#dialecto-inp-swmm-estandar" aria-label="Permalink to &quot;Dialecto INP (SWMM estándar)&quot;">​</a></h2><p>Escrito por <code>inpExporter.generateInp</code> (<code>inpExporter.js:7-715</code>) en un orden de secciones estable:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[TITLE] [OPTIONS] [EVAPORATION] [RAINGAGES] [RDII_DECAY]</span></span>
<span class="line"><span>[SUBCATCHMENTS] [SUBAREAS] [INFILTRATION]</span></span>
<span class="line"><span>[JUNCTIONS] [OUTFALLS] [STORAGE] [DIVIDERS]</span></span>
<span class="line"><span>[CONDUITS] [LOSSES] [PUMPS] [WEIRS] [ORIFICES] [OUTLETS] [XSECTIONS]</span></span>
<span class="line"><span>[TIMESERIES] [TAGS] [REPORT]</span></span>
<span class="line"><span>[COORDINATES] [VERTICES] [POLYGONS] [SYMBOLS]</span></span>
<span class="line"><span>[CURVES] [LID_CONTROLS] [LID_USAGE] [POLLUTANTS] [LANDUSES] [BUILDUP] [WASHOFF]</span></span>
<span class="line"><span>[TREATMENT] [AQUIFERS] [GROUNDWATER] [SNOWPACKS] [SNOWPACK_ASSIGNMENT]</span></span>
<span class="line"><span>+ any unrecognized rawSections re-emitted verbatim (inpExporter.js:696-712)</span></span></code></pre></div><p>Comportamientos clave de exportación: precedencia de opciones valor de UI → <code>opt.raw</code> → default (<code>inpExporter.js:47-50</code>); heurística de <code>REPORT_STEP</code> desde el valor importado → primer intervalo de gage → 1 h (<code>:54-69</code>); desplazamiento de columna OUTFALL para tipos stage (<code>:207-215</code>); manejo de WEIR ROADWAY (<code>:287-295</code>); whitelist de <code>REPORT</code> (<code>:390-403</code>).</p><p>El parser (<code>inpParser.js:7-29</code>) es <strong>sin pérdidas</strong>: cada sección se conserva tokenizada (<code>sections</code>) <em>y</em> cruda (<code>rawSections</code>), para que todo lo que la UI no puede editar sobreviva al export.</p><h2 id="formato-binario-out-salida-de-swmm" tabindex="-1">Formato binario <code>.out</code> (salida de SWMM) <a class="header-anchor" href="#formato-binario-out-salida-de-swmm" aria-label="Permalink to &quot;Formato binario \`.out\` (salida de SWMM)&quot;">​</a></h2><p>Parseado por <code>swmmOutParser.js</code>: magic del footer <code>516114522</code>, header de versión/unidades de flujo, tablas de nombres de IDs con largo prefijado, conteos de variables por clase de objeto y registros Float32 por período para subcuencas (8 vars), nodos (6), enlaces (5) y sistema (14). Expuesto como vistas typed-array de zero-copy.</p><p>Disposición del footer: los últimos seis INT32 son <code>idNamesOffset, objPropsOffset, resultsOffset, numPeriods, errCode, magicEnd</code>; se valida el valor magic <code>516114522</code>. Caminos calientes: <code>getTimeSeries(type,index,varIndex)</code> (cacheado) y <code>getStepData(type,step,varIndex)</code> para el coloreado del mapa por paso.</p>`,12)])])}const u=o(t,[["render",n]]);export{S as __pageData,u as default};
